    "Questions and little words": [
      ["Unsa kini?","oon-sah kee-NEE","What's this?","kini = this, near me."],
      ["Kinsa siya?","keen-SAHQ see-YAH","Who is he? / Who is she?","siya is he and she."],
      ["Asa ka?","ah-sah kah","Where are you going?","Literally \"Where you?\". A common greeting in passing."],
      ["Ngano?","NGAH-noh","Why?","The answer often starts with kay (because)."],
      ["Kanus-a?","kah-noos-ah","When?","The hyphen marks a catch: kanus-a."],
      ["Kanus-a ka mobalik?","kah-noos-ah kah moh-bah-leek","When are you coming back?","ka goes right after the question word."],
      ["Pila?","pee-lah","How many?","Also \"how much\" for a price; Tagpila? asks \"how much each\"."],
      ["Hain?","hah-een","Which one?","Use it when you can point."],
      ["Unsaon pag-adto sa merkado?","oon-sah-ohn pahg-ahd-toh sah mehr-kah-doh","How do I get to the market?","unsaon = how (to do something)."],
      ["Amerikano ka ba?","ah-meh-ree-kah-noh kah bah","Are you American?","ba makes a yes / no question. A woman: Amerikana."],
      ["Oo.","oh-oh","Yes.","Two syllables: o-o."],
      ["Dili.","dee-lee","No.","Also \"not\". For \"didn't\" and \"there isn't\", wala."],
      ["kay","kai","because",""],
      ["ikaw ug ako","ee-KOW oog ah-KOH","you and me","ug = and. og (with an o) is a different word."],
      ["pero","peh-roh","but",""],
      ["tubig o kape","TOO-beeg oh kah-peh","water or coffee","o = or."],
      ["kung gusto nimo","koong goos-toh nee-moh","if you want","kung = if."]
    ],
    "Everyday verbs": [
      ["Mokaon ko.","moh-kah-ohn koh","I'll eat.","mo- = future form."],
      ["Nikaon na ko.","nee-kah-ohn nah koh","I've already eaten.","ni- = past form; na = already."],
      ["Nagluto siya.","nahg-loo-toh see-YAH","She's cooking. / She cooked.","nag- covers both."],
      ["Gipalit nako.","ghee-pah-leet NAH-kohq","I bought it.","Thing-focus: the doer takes nako."],
      ["Makaadto ka?","mah-kah-ahd-toh kah","Can you go?","maka- = can."],
      ["Moinom ko og tubig.","moh-ee-nohm koh ohg TOO-beeg","I'll drink some water.","og before an indefinite thing."],
      ["Nipalit ko og saging.","nee-pah-leet koh ohg SAH-gheeng","I bought some bananas.","Also written mipalit."],
      ["Moadto ko sa merkado.","moh-ahd-toh koh sah mehr-kah-doh","I'll go to the market.","sa = to."],
      ["Mobalik ko.","moh-bah-leek koh","I'll be back.",""],
      ["Nagtrabaho siya sa Cebu.","nahg-trah-bah-hoh see-YAH sah seh-BOO","He works in Cebu.","nag- = doing now, or done. Also \"she\"."],
      ["Magtuon ko.","mahg-too-ohn koh","I'll study.","Some verbs take mag- instead of mo-: learn each with its prefix."],
      ["Matulog na ko.","mah-too-lohg nah koh","I'm going to sleep now.","na = now, already."],
      ["Paliton nako.","pah-lee-tohn NAH-kohq","I'll buy it.","-on = future, with the thing as the focus."],
      ["Kaonon nako ang mangga.","kah-oh-nohn NAH-kohq ahng mahng-gah","I'll eat the mango.","With -on the thing gets ang."],
      ["Gihimo nako.","ghee-hee-moh NAH-kohq","I made it.","gi- = past, with the thing as the focus."],
      ["Nakaadto na ka sa Bohol?","nah-kah-ahd-toh nah kah sah boh-hohl","Have you ever been to Bohol?","naka- = have ever, managed to."],
      ["Kaon na ta.","KAH-ohn nah tah","Let's eat.","ta = we, including you."]
    ],
