      {"t":"type","p":"Where are you from?","a":["Taga-asa ka","Taga-asa ikaw"],"hint":"taga- · asa · ka","x":["gikan"],"why":"The short pronoun ka goes in second place: Taga-asa ka?"},
      {"t":"type","p":"What's your name?","a":["Unsay imong ngalan","Unsa ang imong ngalan","Unsa imong ngalan"],"hint":"unsa · imong · ngalan","x":["ako"],"why":"imong is the akong-set word for your: it goes before the noun."}
